Definition source_AST_127_0003 := row_to_tm [t1LB;t0RD;t1LC;t0LB;t1RD;t0LA;t1RA;t0RC].
Definition perm_AST_127_0003(q:St):St := match q with StA=>StB | StB=>StC | StC=>StD | StD=>StA end.
Definition skip_AST_127_0003(t:Instr):bool := instr_eqb t (StB,S1).

(* spec 1RB0LC_1RC0RA_1LD0RB_1LA0LD *)
Definition r_AST_127_0000 : list (option Trans) := [t1RB;t0LC;t1RC;t0RA;t1LD;t0RB;t1LA;t0LD].
Lemma cv_AST_127_0000 : coversTr (row_to_tm r_AST_127_0000).
Proof. assert(Hhit:finite_instr_hit(row_to_tm r_AST_127_0000)(StC,S1)).
  { apply(finite_instr_conjugate source_AST_127_0000 _ perm_AST_127_0000 false (StA,S1)).
    - intros[] [];reflexivity.
    - intros[];first[exists StA;reflexivity|exists StB;reflexivity|
                    exists StC;reflexivity|exists StD;reflexivity].
    - intro c. apply pd_finite;reflexivity. }
  assert(Htotal:forall q s,exists tr,row_to_tm r_AST_127_0000 q s=Some tr)
    by(intros[] [];eexists;reflexivity).
  pose proof(finite_instr_recurrent _ _ Htotal Hhit)as Hrec.
  apply coversTr_nqh,neverqhtr_mirror.
  apply(ngram_check_neverqh_fuelmixtr_except_sound _ 3 0 5240 20
    skip_AST_127_0000 cert_AST_127_0000).
  - intros[[] []] H N;try discriminate.
    destruct(Hrec N)as(j&Hj&Hf). exists j;split;[exact Hj|apply mirror_fires;exact Hf].
  - vm_compute;reflexivity. Qed.

